// The icon audit found these seven vendored marks bake a fixed hex fill
// with no background shape of their own: `express`/`github` bake
// near-white (invisible on the light theme, the same class PR3 found in
// the social icons); `aws`/`linux`/`postgresql` bake near-black
// (invisible on the dark theme — the mirror-image failure); `nextjs` and
// the hand-authored `cicd` are borderline. Rendered inline below instead
// of via `<img src={svgsConstants[...]}>`, exactly the pattern PR3
// established for the social links (`Home.tsx`'s `SocialIcon`).
type MonoIconKey =
  | "express"
  | "github"
  | "aws"
  | "linux"
  | "postgresql"
  | "nextjs"
  | "cicd"
  | "claudecode"
  | "codex"
  | "opencode"
  | "herdr"
  | "gentleai"
  | "speckit"
  | "openspec";

const MONO_ICON_KEYS: readonly MonoIconKey[] = [
  "express",
  "github",
  "aws",
  "linux",
  "postgresql",
  "nextjs",
  "cicd",
  "claudecode",
  "codex",
  "opencode",
  "herdr",
  "gentleai",
  "speckit",
  "openspec",
];

function isMonoIconKey(item: svgs): item is MonoIconKey {
  return (MONO_ICON_KEYS as readonly string[]).includes(item);
}

/**
 * Inline, theme-aware brand marks, `currentColor` throughout — no
 * hardcoded hex anywhere here. `express`, `github`, `aws`, and `nextjs`
 * reuse the exact path data already shipped in `src/assets/`, just
 * recolored; `github`'s paths are identical to `Home.tsx`'s already
 * theme-safe `SocialIcon`. `cicd` is our own PR1 asset with its
 * hardcoded `stroke="#8E99B0"` (the literal dark-theme `--text-muted`
 * value) corrected to `currentColor`. `linux` and `postgresql` are
 * rebuilt as simplified penguin/elephant pictograms from basic shapes
 * rather than the original multi-tone illustrations — those bake most
 * of their recognizable detail (the belly patch, the eye highlights)
 * as separate light-colored layers that would merge into the body and
 * disappear once every layer is forced to one flat color.
 *
 * The AI-tooling group below adds seven more entries. Five carry an
 * official vector mark recolored to `currentColor` the same way as the
 * rest of this function: `claudecode` and `openspec` are already
 * single-path brand assets; `codex` reuses OpenAI's mark since Codex
 * has no brand mark of its own; `opencode` and `herdr` are vendored
 * two-tone brand assets (background/foreground split) collapsed to one
 * `currentColor` shape, exactly like `linux`/`postgresql` above. Two —
 * `gentleai` and `speckit` — have no official vector mark to adapt
 * (only raster PNG/GIF/WebP brand assets), so they fall back to
 * neutral, non-brand Lucide stroke glyphs ("layers", "file-text")
 * instead of tracing a lookalike.
 */
